// Project Euler 99: identify the largest exponential in the supplied base/exponent list.
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public class Problem099 {
    private static final String DATA = "";
    public static void main(String[] args) throws Exception {
        String data;
        try (InputStream in = new java.util.zip.GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(DATA)))) { data = new Scanner(in, "US-ASCII").useDelimiter("\\A").next(); }
        double largest = Double.NEGATIVE_INFINITY; int line = 0, answer = 0;
        for (String record : data.split("\\R")) {
            line++; String[] fields = record.split(",");
            double magnitude = Integer.parseInt(fields[1]) * Math.log(Integer.parseInt(fields[0]));
            if (magnitude > largest) { largest = magnitude; answer = line; }
        }
        System.out.println(answer);
    }
}
